countries.sparql:
SELECT ?c ?en ?ar ?iso (GROUP_CONCAT(DISTINCT ?enAlt; separator="|") AS ?enAlts) (GROUP_CONCAT(DISTINCT ?arAlt; separator="|") AS ?arAlts) (GROUP_CONCAT(DISTINCT ?cap; separator="|") AS ?caps) (MAX(?pop) AS ?p) WHERE {
  { ?c wdt:P31 wd:Q3624078 } UNION { VALUES ?c { wd:Q219060 } }
  FILTER NOT EXISTS { ?c wdt:P576 ?end }
  OPTIONAL { ?c wdt:P297 ?iso } OPTIONAL { ?c wdt:P1082 ?pop } OPTIONAL { ?c wdt:P36 ?cap }
  OPTIONAL { ?c rdfs:label ?en FILTER(LANG(?en)="en") } OPTIONAL { ?c rdfs:label ?ar FILTER(LANG(?ar)="ar") }
  OPTIONAL { ?c skos:altLabel ?enAlt FILTER(LANG(?enAlt)="en") } OPTIONAL { ?c skos:altLabel ?arAlt FILTER(LANG(?arAlt)="ar") }
} GROUP BY ?c ?en ?ar ?iso

cities.sparql:
SELECT ?c ?en ?ar (MAX(?pop) AS ?p) (SAMPLE(?cc) AS ?country) (GROUP_CONCAT(DISTINCT ?enAlt; separator="|") AS ?enAlts) (GROUP_CONCAT(DISTINCT ?arAlt; separator="|") AS ?arAlts) WHERE {
  ?c wdt:P1082 ?pop . FILTER(?pop >= 1000000)
  ?c wdt:P31/wdt:P279* wd:Q515 .
  FILTER NOT EXISTS { ?c wdt:P576 ?end }
  OPTIONAL { ?c wdt:P17 ?cc }
  OPTIONAL { ?c rdfs:label ?en FILTER(LANG(?en)="en") } OPTIONAL { ?c rdfs:label ?ar FILTER(LANG(?ar)="ar") }
  OPTIONAL { ?c skos:altLabel ?enAlt FILTER(LANG(?enAlt)="en") } OPTIONAL { ?c skos:altLabel ?arAlt FILTER(LANG(?arAlt)="ar") }
} GROUP BY ?c ?en ?ar

capitals.sparql:
SELECT ?c ?en ?ar (SAMPLE(?cc) AS ?country) (MAX(?pop) AS ?p) (GROUP_CONCAT(DISTINCT ?enAlt; separator="|") AS ?enAlts) (GROUP_CONCAT(DISTINCT ?arAlt; separator="|") AS ?arAlts) WHERE {
  { ?cc wdt:P31 wd:Q3624078 } UNION { VALUES ?cc { wd:Q219060 } }
  ?cc wdt:P36 ?c . OPTIONAL { ?c wdt:P1082 ?pop }
  OPTIONAL { ?c rdfs:label ?en FILTER(LANG(?en)="en") } OPTIONAL { ?c rdfs:label ?ar FILTER(LANG(?ar)="ar") }
  OPTIONAL { ?c skos:altLabel ?enAlt FILTER(LANG(?enAlt)="en") } OPTIONAL { ?c skos:altLabel ?arAlt FILTER(LANG(?arAlt)="ar") }
} GROUP BY ?c ?en ?ar

